mapper.select:
SELECT t.id, t.rate_code, t.rate_name, t.apply_scene, t.rate_rule, t.effect_time, t.expire_time, t.apply_station, t.apply_group, t.rate_status, t.remark, t.reserve1, t.reserve2, t.create_time, t.update_time, t.creator, t.updater, IFNULL(GROUP_CONCAT(s.station_name SEPARATOR '，'), '') AS station_names FROM rate_setting t LEFT JOIN charging_station s ON FIND_IN_SET(s.id, t.apply_station)
1=1 and t.deleted = 0
AND t.rate_code LIKE CONCAT('%', #{rateCode}, '%')
AND t.rate_name LIKE CONCAT('%', #{rateName}, '%')
AND t.apply_scene LIKE CONCAT('%', #{applyScene}, '%')
AND t.rate_rule LIKE CONCAT('%', #{rateRule}, '%')
AND t.rate_status = #{rateStatus}
AND t.apply_station LIKE CONCAT('%', #{applyStation}, '%')
AND t.apply_group LIKE CONCAT('%', #{applyGroup}, '%')
AND t.remark LIKE CONCAT('%', #{remark}, '%')
AND t.reserve1 LIKE CONCAT('%', #{reserve1}, '%')
AND t.reserve2 LIKE CONCAT('%', #{reserve2}, '%')
AND t.effect_time >= #{effectTime}
AND t.expire_time <= #{expireTime}
AND t.create_time BETWEEN #{createTime[0]} AND #{createTime[1]}
AND t.create_time >= #{startTime}
AND t.create_time <= #{endTime}
GROUP BY t.id ORDER BY t.id desc,t.id LIMIT #{pageSize} OFFSET ${(pageNo - 1) * pageSize}

SELECT COUNT(DISTINCT t.id)
FROM rate_setting t

    1=1 and t.deleted = 0

        AND t.rate_code LIKE CONCAT('%', #{rateCode}, '%')


        AND t.rate_name LIKE CONCAT('%', #{rateName}, '%')


        AND t.apply_scene LIKE CONCAT('%', #{applyScene}, '%')


        AND t.rate_rule LIKE CONCAT('%', #{rateRule}, '%')


        AND t.rate_status = #{rateStatus}


        AND t.apply_station LIKE CONCAT('%', #{applyStation}, '%')


        AND t.apply_group LIKE CONCAT('%', #{applyGroup}, '%')


        AND t.remark LIKE CONCAT('%', #{remark}, '%')


        AND t.reserve1 LIKE CONCAT('%', #{reserve1}, '%')


        AND t.reserve2 LIKE CONCAT('%', #{reserve2}, '%')





        AND t.effect_time >= #{effectTime}



        AND t.expire_time <= #{expireTime}



        AND t.create_time BETWEEN #{createTime[0]} AND #{createTime[1]}


        AND t.create_time >= #{startTime}


        AND t.create_time <= #{endTime}

select count(*) as totalRateCount, SUM(CASE WHEN t.rate_status = '已生效' THEN 1 ELSE 0 END) AS enableCount , SUM(CASE WHEN t.rate_status = '未生效' THEN 1 ELSE 0 END) AS unEnableCount , SUM(CASE WHEN t.rate_status = '已失效' THEN 1 ELSE 0 END) AS disableCount , CASE WHEN count(*) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN t.rate_status = '已生效' THEN 1 ELSE 0 END) / count(*) * 100, 1) END AS enableRatio from rate_setting t where t.deleted=0
AND FIND_IN_SET(#{stationId}, t.apply_station)
AND t.create_time >= #{startTime}
AND t.create_time <= #{endTime}

select t.rate_name as gradeType, count(*) as count from rate_setting t where t.deleted=0
AND FIND_IN_SET(#{stationId}, t.apply_station)
AND t.create_time >= #{startTime}
AND t.create_time <= #{endTime}
group by t.rate_name

SELECT s.station_id as stationId, c.station_name as stationName, COUNT(*) AS rateCount FROM ( -- 拆分 apply_station 逗号分隔的场站ID SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(t.apply_station, ',', b.help_topic_id + 1), ',', -1) AS station_id FROM rate_setting t JOIN mysql.help_topic b ON b.help_topic_id < (LENGTH(t.apply_station) - LENGTH(REPLACE(t.apply_station, ',', '')) + 1) WHERE t.deleted = 0
AND t.create_time >= #{startTime}
AND t.create_time <= #{endTime}
) s left join charging_station c on c.id = s.station_id WHERE s.station_id != '' AND s.station_id IS NOT NULL GROUP BY s.station_id,c.station_name ORDER BY s.station_id desc,c.station_name DESC
